<script lang="ts">
import {onDestroy} from 'svelte';let box:HTMLDivElement;let running=false;let available=true;let cleanup=()=>{};
async function launch(){if(running)return;running=true;try{const T=await import('three');const renderer=new T.WebGLRenderer({antialias:true,alpha:true});renderer.setSize(box.parentElement!.clientWidth,300);box.appendChild(renderer.domElement);const scene=new T.Scene(),camera=new T.PerspectiveCamera(38,box.parentElement!.clientWidth/300,.1,100);camera.position.set(7,6,8);camera.lookAt(0,0,0);scene.add(new T.AmbientLight(0xffffff,2));const light=new T.DirectionalLight(0xffffff,3);light.position.set(4,7,5);scene.add(light);const group=new T.Group();const geometries:any[]=[],materials:any[]=[];[0x7446ae,0x008b67,0xf5c842,0xf15a24].forEach((c,i)=>{const geo=new T.BoxGeometry(5,.65,3),mat=new T.MeshStandardMaterial({color:c,roughness:.8});geometries.push(geo);materials.push(mat);const mesh=new T.Mesh(geo,mat);mesh.position.y=i*.8-1.2;group.add(mesh)});scene.add(group);let drag=false,last=0;const down=(e:PointerEvent)=>{drag=true;last=e.clientX;renderer.domElement.setPointerCapture(e.pointerId)},move=(e:PointerEvent)=>{if(drag){group.rotation.y+=(e.clientX-last)*.012;last=e.clientX;renderer.render(scene,camera)}},up=()=>drag=false;renderer.domElement.addEventListener('pointerdown',down);renderer.domElement.addEventListener('pointermove',move);renderer.domElement.addEventListener('pointerup',up);renderer.render(scene,camera);cleanup=()=>{renderer.domElement.removeEventListener('pointerdown',down);renderer.domElement.removeEventListener('pointermove',move);renderer.domElement.removeEventListener('pointerup',up);geometries.forEach(g=>g.dispose());materials.forEach(m=>m.dispose());renderer.dispose();renderer.domElement.remove()}}catch{available=false;running=false}}
onDestroy(()=>cleanup());
</script>
<div class="model"><div><strong>换一个角度，看地层。</strong><p>拖动模型观察层位空间关系。概念示意，无自动旋转；不支持三维时可继续阅读二维剖面。</p></div><button onclick={launch} disabled={running}>{running?'拖动下方地层模型':available?'加载可旋转三维地层 ↗':'三维不可用，请查看二维图'}</button><div class="viewport" bind:this={box}></div></div>
<style>.model{border-top:1px solid #dacbb5;padding:25px 0}.model p{font-size:12px;color:#776957;line-height:1.8}.viewport{width:100%;overflow:hidden}.viewport:empty{display:none}.viewport :global(canvas){max-width:100%;touch-action:none}</style>
